My forward pass matches EVAL, and skill 3 is perfect, but the one-pass reads are biased by clipping because each row sees different columns. I am switching to row-against-row differences on shared unclipped columns, which needs no iteration and should remove that bias.
```python
T=np.load("T.npy")
def hop(D):
    n=len(D);F=D.copy()
    for a in range(n):
        for r in range(n):
            if a!=r and np.isnan(F[a,r]):
                x=D[a]+D[:,r]
                if np.isfinite(x).any(): F[a,r]=np.nanmedian(x)
    return F
def pair(Y,m,minn=3):
    n=Y.shape[0];D=np.full((n,n),np.nan)
    for a in range(n):
        D[a,a]=0
        for r in range(n):
            if a!=r:
                sh=m[a]&m[r]
                if sh.sum()>=minn: D[a,r]=(Y[a][sh]-Y[r][sh]).mean()
    F=hop(D)
    ok=np.isfinite(F).sum(1)>1
    out=np.full(n,np.nan)
    with np.errstate(all='ignore'):
        out[ok]=np.nanmean(F[ok],1)
    return out
def read2p(M):
    O=M>=0;m=O&(M>=1)&(M<=6);Y=np.where(O,M,0).astype(float)
    U=pair(Y,m);V=pair(Y.T,m.T)
    U=np.where(np.isnan(U),np.nanmin(U),U);V=np.where(np.isnan(V),np.nanmin(V),V)
    c=(Y-U[:,None]-V[None,:])[m].mean();return U,V+c
def read1p(M):
    O=M>=0;m=O&(M>=1)&(M<=6);Y=np.log(np.where(O,M,0)+0.5)
    U=pair(Y,m,2);V=pair(Y.T,m.T,2)
    Uf=np.where(np.isnan(U),0,U);Vf=np.where(np.isnan(V),0,V)
    c=(Y-Uf[:,None]-Vf[None,:])[m].mean();Vf=Vf+c
    for name,arr,other in (("u",Uf,Vf),("v",Vf,Uf)):
        pass
    u=np.exp(Uf);v=np.exp(Vf)
    u=np.where(np.isnan(U),0.5/v.max(),u);v=np.where(np.isnan(V),0.5/u.max(),v)
    return u,v
P={1:lambda U,V:np.clip(np.floor(U[:,None]*V[None,:]),0,7),2:lambda U,V:np.clip(np.round(U[:,None]+V[None,:]),0,7),0:lambda U,V:np.clip(np.floor(np.abs(U[:,None]-V[None,:])),0,7)}
