def hop(D):
    n=len(D);F=D.copy()
    for a in range(n):
        for r in range(n):
            if a!=r and np.isnan(F[a,r]):
                x=D[a]+D[:,r]
                if np.isfinite(x).any(): F[a,r]=np.nanmedian(x)
    return F
def side(Y,m,a0,b0,mg):
    n=len(a0);D=np.full((n,n),np.nan)
    for a in range(n):
        D[a,a]=0
        for r in range(n):
            if a==r: continue
            sh=m[a]&m[r]
            pos=sh&(b0<min(a0[a],a0[r])-mg);neg=sh&(b0>max(a0[a],a0[r])+mg)
            d=np.r_[Y[a][pos]-Y[r][pos],-(Y[a][neg]-Y[r][neg])]
            if len(d)>=3: D[a,r]=d.mean()
    F=hop(D)
    with np.errstate(all='ignore'): return np.nanmean(F,1)
def read0p(M,U0,V0,mg):
    O=M>=0;un=O&(M<7);X=np.where(O,M,0).astype(float);far=un&(M>=2)
    U=side(X,un,U0,V0,mg);V=side(X.T,un.T,V0,U0,mg)
    s=np.sign(U0[:,None]-V0[None,:])
    c=(U[:,None]-V[None,:]-s*(X+.5))[far].mean();V=V+c
    return U,V
